+    @Override
+    public void initialize(Properties properties) {
+        Properties configuration = properties == null ? new Properties() : properties;
+        storeCreationAllowed = Boolean.parseBoolean(configuration.getProperty(
+                ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(configuration.getProperty(
+                ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = IntegrityMode.from(configuration.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
+        ruleViolationFileNameStrategy = configureFileNameStrategy(configuration);
+        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires store updates to be enabled (enable %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
