+    private static String createDescriptionFileName(String description) {
+        List<String> words = new ArrayList<>();
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
+        while (matcher.find()) {
+            words.add(matcher.group(1));
+        }
+
+        LinkedHashSet<String> selected = new LinkedHashSet<>();
+        int humanPartLimit = 160;
+        int prefixLimit = 80;
+        int length = 0;
+        for (String word : words) {
+            int newLength = length + (selected.isEmpty() ? 0 : 1) + word.length();
+            if (newLength > prefixLimit) {
+                break;
+            }
+            selected.add(word);
+            length = newLength;
+        }
+        for (int i = words.size() - 1; i >= 0; i--) {
+            String word = words.get(i);
+            if (selected.contains(word)) {
+                continue;
+            }
+            int newLength = length + (selected.isEmpty() ? 0 : 1) + word.length();
+            if (newLength > humanPartLimit) {
+                if (selected.isEmpty() && word.length() <= humanPartLimit) {
+                    selected.add(word);
+                    length = word.length();
+                }
+                continue;
+            }
+            selected.add(word);
+            length = newLength;
+        }
+
+        String humanPart = selected.isEmpty() ? "rule" : joinWithHyphens(selected);
+        String hash = descriptionHash(description);
+        String result = humanPart + "-" + hash;
+        if (result.length() > 200) {
+            result = hash;
+        }
+        return STORED_RULES_FILE_NAME.equals(result) ? "rule-" + hash : result;
+    }
+
+    private static String joinWithHyphens(Iterable<String> words) {
+        StringBuilder result = new StringBuilder();
+        for (String word : words) {
+            if (result.length() > 0) {
+                result.append('-');
+            }
+            result.append(word);
+        }
+        return result.toString();
+    }
+
+    private static String descriptionHash(String description) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(description.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder();
+            for (int i = 0; i < 16; i++) {
+                result.append(String.format("%02x", digest[i] & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
