+    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile) {
+        try {
+            return STORED_RULES_BY_PATH.computeIfAbsent(storedRulesFile.getCanonicalPath(), path -> new FileSyncedProperties(storedRulesFile));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private File getStoredRulesFile() {
+        File rulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
+        if (!existsWithoutFollowingLinks(rulesFile.toPath()) && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+        return rulesFile;
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storedRules) {
+            return storedRules.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+        synchronized (storedRules) {
+            String description = rule.getDescription();
+            String existingFileName = storedRules.getProperty(description);
+            if (integrityMode == IntegrityMode.REPAIR && violations.isEmpty()) {
+                if (existingFileName != null) {
+                    forgetKnownRule(description, existingFileName);
+                }
+                return;
+            }
+
+            if (existingFileName == null) {
+                String candidateFileName = nameFor(description);
+                Path candidate = safeNewFilePath(candidateFileName);
+                writeNewFile(candidate, violations);
+                try {
+                    storedRules.putAndSync(description, candidateFileName);
+                } catch (RuntimeException e) {
+                    deleteQuietly(candidate);
+                    throw e;
+                }
+                log.trace("Assigning new file {} to rule '{}'", candidateFileName, description);
+            } else {
+                Path target = safeExistingFilePath(existingFileName);
+                writeFile(target, violations);
+                log.trace("Rule '{}' is already stored in file {}", description, existingFileName);
+            }
+        }
+    }
+
+    private void forgetKnownRule(String description, String existingFileName) {
+        Entry entry = entryForSave(description, existingFileName);
+        boolean shared = isSharedWithAnotherEntry(entry, storedRules.snapshot());
+        StagedChange deletion = null;
+        try {
+            if (entry.resolvedFile != null && !shared) {
+                deletion = stageDelete(entry);
+            }
+            Properties updated = storedRules.snapshot();
+            updated.remove(entry.propertyKey);
+            storedRules.replaceAndSync(updated);
+            if (deletion != null) {
+                deletion.commit();
+            }
+        } catch (RuntimeException e) {
+            if (deletion != null) {
+                deletion.rollback();
+            }
+            throw asStoreUpdateFailure(e);
+        }
+    }
+
+    private Entry entryForSave(String description, String recordedName) {
+        ResolvedFile resolvedFile = resolveRecordedFile(recordedName);
+        if (resolvedFile.invalidReason != null && resolvedFile.pathExists) {
+            throw new StoreUpdateFailedException("Cannot safely update stored rule '" + description + "': " + resolvedFile.invalidReason);
+        }
+        Entry result = new Entry(description, description, recordedName, null, resolvedFile);
+        result.shared = false;
+        return result;
+    }
+
+    private boolean isSharedWithAnotherEntry(Entry entry, Properties snapshot) {
+        for (String key : snapshot.stringPropertyNames()) {
+            if (key.equals(entry.propertyKey)) {
+                continue;
+            }
+            String value = snapshot.getProperty(key);
+            if (entry.recordedName.equals(value)) {
+                return true;
+            }
+            if (entry.resolvedFile != null && entry.resolvedFile.path != null) {
+                ResolvedFile other = resolveRecordedFile(value);
+                if (other.path != null && sameFile(entry.resolvedFile.path, other.path)) {
+                    return true;
+                }
+            }
+        }
+        return false;
+    }
+
+    private String nameFor(String description) {
+        String name;
+        try {
+            name = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+        if (name == null || name.trim().isEmpty()) {
+            throw new StoreUpdateFailedException("Rule violation file name strategy returned no name for rule '" + description + "'");
+        }
+        return name;
+    }
+
+    private Path safeNewFilePath(String fileName) {
+        Path path = safePath(fileName, false);
+        if (path == null || STORED_RULES_FILE_NAME.equals(fileName)) {
+            throw new StoreUpdateFailedException("Rule violation file name must name a regular file directly in the store folder and must not be stored.rules: " + fileName);
+        }
+        if (existsWithoutFollowingLinks(path)) {
+            throw new StoreUpdateFailedException("Rule violation file already exists or is occupied: " + fileName);
+        }
+        Properties snapshot = storedRules.snapshot();
+        for (String key : snapshot.stringPropertyNames()) {
+            String recordedName = snapshot.getProperty(key);
+            if (fileName.equals(recordedName)) {
+                throw new StoreUpdateFailedException("Rule violation file name is already recorded for another rule: " + fileName);
+            }
+            ResolvedFile recorded = resolveRecordedFile(recordedName);
+            if (recorded.path != null && sameFile(path, recorded.path)) {
+                throw new StoreUpdateFailedException("Rule violation file name is already occupied by another rule: " + fileName);
+            }
+        }
+        return path;
+    }
+
+    private Path safeExistingFilePath(String fileName) {
+        if (STORED_RULES_FILE_NAME.equals(fileName)) {
+            throw new StoreUpdateFailedException("A rule violation file must not be stored.rules");
+        }
+        Path path = safePath(fileName, true);
+        ResolvedFile resolved = resolveRecordedFile(fileName);
+        if (resolved.invalidReason != null) {
+            if (!resolved.pathExists && path != null) {
+                return path;
+            }
+            throw new StoreUpdateFailedException("Cannot safely update rule violation file '" + fileName + "': " + resolved.invalidReason);
+        }
+        return resolved.path;
+    }
+
+    private Path safePath(String fileName, boolean allowMissing) {
+        try {
+            File candidate = new File(storeFolder, fileName);
+            File canonical = candidate.getCanonicalFile();
+            File canonicalFolder = storeFolder.getCanonicalFile();
+            if (!canonicalFolder.equals(canonical.getParentFile())) {
+                return null;
+            }
+            if (!allowMissing && existsWithoutFollowingLinks(candidate.toPath())) {
+                return null;
+            }
+            return canonical.toPath();
+        } catch (IOException e) {
+            return null;
+        }
+    }
+
+    private void writeNewFile(Path target, List<String> violations) {
+        try {
+            writeFileAtomically(target, encodedViolations(violations), false);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void writeFile(Path target, List<String> violations) {
+        try {
+            writeFileAtomically(target, encodedViolations(violations), true);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private byte[] encodedViolations(List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append('\n');
+        }
+        return builder.toString().getBytes(UTF_8);
+    }
+
+    private void writeFileAtomically(Path target, byte[] content, boolean replace) throws IOException {
+        Path temporary = Files.createTempFile(storeFolder.toPath(), ".archunit-violation-", ".tmp");
+        try {
+            Files.write(temporary, content, StandardOpenOption.TRUNCATE_EXISTING);
+            if (replace) {
+                moveReplacing(temporary, target);
+            } else {
+                moveWithoutReplacing(temporary, target);
+            }
+        } finally {
+            Files.deleteIfExists(temporary);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\r", "\\\r").replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\r", "\r").replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storedRules) {
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            Path file = safeReadPath(ruleDetailsFileName);
+            List<String> result = readLines(file);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private Path safeReadPath(String fileName) {
+        ResolvedFile resolved = resolveRecordedFile(fileName);
+        if (resolved.path == null) {
+            throw new StoreReadException(new IOException("Unsafe stored rule file name: " + fileName));
+        }
+        return resolved.path;
+    }
+
+    private List<String> readLines(Path file) {
+        String violationsText = readStoreFile(file);
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .filter(line -> !onlyLineBreaks(line))
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private boolean onlyLineBreaks(String value) {
+        for (int i = 0; i < value.length(); i++) {
+            if (value.charAt(i) != '\r') {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private String readStoreFile(Path file) {
+        try {
+            // CRLF is a line ending. A lone CR is deliberately not normalized: it can be part of a violation.
+            return new String(toByteArray(file.toFile()), UTF_8).replace("\r\n", "\n");
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private IntegrityReport inspect(Properties snapshot) {
+        List<Entry> entries = new ArrayList<>();
+        for (String propertyKey : new TreeSet<>(snapshot.stringPropertyNames())) {
+            String recordedName = snapshot.getProperty(propertyKey);
