@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String FILE_NAMES_DEFAULT = "random";
    private static final String RANDOM_FILE_NAMES = "random";
    private static final String DESCRIPTION_FILE_NAMES = "description";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_DEFAULT = "ignore";

    /* The object is both the in-process lock and the in-memory index cache. */
    private static final ConcurrentHashMap<String, FileSyncedProperties> STORED_RULES_BY_PATH = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy constructorStrategy;
    private final boolean hasConstructorStrategy;

    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private File storeFolder;
    private FileSyncedProperties storedRules;
    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    private IntegrityMode integrityMode;
    private boolean builtInRandomFileNames;

    /**
     * Creates a standard store. New files are named randomly unless {@code default.fileNames=description} is configured.
     */
    public TextFileBasedViolationStore() {
        constructorStrategy = null;
        hasConstructorStrategy = false;
    }

    /**
     * Creates a store with a custom rule violation file naming strategy.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        checkArgument(ruleViolationFileNameStrategy != null, "Rule violation file name strategy must not be null");
        constructorStrategy = ruleViolationFileNameStrategy;
        hasConstructorStrategy = true;
    }

    @Override
    public void initialize(Properties properties) {
        Properties configuration = properties == null ? new Properties() : properties;
        storeCreationAllowed = Boolean.parseBoolean(configuration.getProperty(
                ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(configuration.getProperty(
                ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = IntegrityMode.from(configuration.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        ruleViolationFileNameStrategy = configureFileNameStrategy(configuration);
        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity repair requires store updates to be enabled (enable %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        String path = configuration.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT);
        try {
            storeFolder = new File(path).getCanonicalFile();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }

        File storedRulesFile = getStoredRulesFile();
        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());
        storedRules = getOrCreateStoredRules(storedRulesFile);
        synchronized (storedRules) {
            boolean indexExists = storedRules.prepareForInspection();
            Properties snapshot = storedRules.snapshot();

            if (integrityMode == IntegrityMode.IGNORE) {
                storedRules.createIfAbsent();
                return;
            }

            IntegrityReport report = inspect(snapshot);
            if (integrityMode == IntegrityMode.FAIL) {
                if (report.hasProblems()) {
                    throw new StoreInitializationFailedException(report.asMessage());
                }
                if (!indexExists) {
                    storedRules.createIfAbsent();
                }
                return;
            }

            repair(report, snapshot);
            if (!indexExists) {
                storedRules.createIfAbsent();
            }
        }
    }

    private RuleViolationFileNameStrategy configureFileNameStrategy(Properties properties) {
        if (hasConstructorStrategy) {
            builtInRandomFileNames = false;
            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
                throw new StoreInitializationFailedException(String.format(
                        "Property %s cannot be configured when a file name strategy was supplied to the constructor",
                        FILE_NAMES_PROPERTY_NAME));
            }
            return constructorStrategy;
        }

        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_DEFAULT);
        if (RANDOM_FILE_NAMES.equals(configured)) {
            builtInRandomFileNames = true;
            return __ -> UUID.randomUUID().toString();
        }
        builtInRandomFileNames = false;
        if (DESCRIPTION_FILE_NAMES.equals(configured)) {
            return TextFileBasedViolationStore::createDescriptionFileName;
        }
        return instantiateStrategy(configured);
    }

    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
        try {
            Class<?> strategyClass = Class.forName(className);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
                throw new IllegalArgumentException("not a RuleViolationFileNameStrategy");
            }
            Constructor<?> constructor = strategyClass.getConstructor();
            return (RuleViolationFileNameStrategy) constructor.newInstance();
        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException
                 | InvocationTargetException | ClassCastException | IllegalArgumentException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot instantiate rule violation file name strategy '%s'", className), e);
        }
    }

    private static String createDescriptionFileName(String description) {
        List<String> words = new ArrayList<>();
        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
        while (matcher.find()) {
            words.add(matcher.group(1));
        }

        LinkedHashSet<String> selected = new LinkedHashSet<>();
        int humanPartLimit = 160;
        int prefixLimit = 80;
        int length = 0;
        for (String word : words) {
            int newLength = length + (selected.isEmpty() ? 0 : 1) + word.length();
            if (newLength > prefixLimit) {
                break;
            }
            selected.add(word);
            length = newLength;
        }
        for (int i = words.size() - 1; i >= 0; i--) {
            String word = words.get(i);
            if (selected.contains(word)) {
                continue;
            }
            int newLength = length + (selected.isEmpty() ? 0 : 1) + word.length();
            if (newLength > humanPartLimit) {
                if (selected.isEmpty() && word.length() <= humanPartLimit) {
                    selected.add(word);
                    length = word.length();
                }
                continue;
            }
            selected.add(word);
            length = newLength;
        }

        String humanPart = selected.isEmpty() ? "rule" : joinWithHyphens(selected);
        String hash = descriptionHash(description);
        String result = humanPart + "-" + hash;
        if (result.length() > 200) {
            result = hash;
        }
        }
        return STORED_RULES_FILE_NAME.equals(result) ? "rule-" + hash : result;
    }

    private static String joinWithHyphens(Iterable<String> words) {
        StringBuilder result = new StringBuilder();
        for (String word : words) {
            if (result.length() > 0) {
                result.append('-');
            }
            result.append(word);
        }
        return result.toString();
    }

    private static String descriptionHash(String description) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(description.getBytes(UTF_8));
            StringBuilder result = new StringBuilder();
            for (int i = 0; i < 16; i++) {
                result.append(String.format("%02x", digest[i] & 0xff));
            }
            return result.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile) {
        try {
            return STORED_RULES_BY_PATH.computeIfAbsent(storedRulesFile.getCanonicalPath(), path -> new FileSyncedProperties(storedRulesFile));
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private File getStoredRulesFile() {
        File rulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
        if (!existsWithoutFollowingLinks(rulesFile.toPath()) && !storeCreationAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
        }
        return rulesFile;
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storedRules) {
            return storedRules.containsKey(rule.getDescription());
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }
        synchronized (storedRules) {
            String description = rule.getDescription();
            String existingFileName = storedRules.getProperty(description);
            if (integrityMode == IntegrityMode.REPAIR && violations.isEmpty()) {
                if (existingFileName != null) {
                    forgetKnownRule(description, existingFileName);
                }
                return;
            }

            if (existingFileName == null) {
                String candidateFileName = nameFor(description);
                Path candidate = safeNewFilePath(candidateFileName);
                writeNewFile(candidate, violations);
                try {
                    storedRules.putAndSync(description, candidateFileName);
                } catch (RuntimeException e) {
                    deleteQuietly(candidate);
                    throw asStoreUpdateFailure(e);
                }
                log.trace("Assigning new file {} to rule '{}'", candidateFileName, description);
            } else {
                Path target = safeExistingFilePath(existingFileName);
                writeFile(target, violations);
                log.trace("Rule '{}' is already stored in file {}", description, existingFileName);
            }
        }
    }

    private void forgetKnownRule(String description, String existingFileName) {
        if (isIndexPath(existingFileName)) {
            throw new StoreUpdateFailedException("A rule violation file must not be stored.rules");
        }
        Entry entry = entryForSave(description, existingFileName);
        boolean shared = isSharedWithAnotherEntry(entry, storedRules.snapshot());
        StagedChange deletion = null;
        Properties original = storedRules.snapshot();
        boolean indexUpdated = false;
        try {
            if (entry.resolvedFile != null && !shared) {
                deletion = stageDelete(entry);
            }
            Properties updated = storedRules.snapshot();
            updated.remove(entry.propertyKey);
            storedRules.replaceAndSync(updated);
            indexUpdated = true;
            if (deletion != null) {
                deletion.commit();
            }
        } catch (RuntimeException e) {
            if (indexUpdated) {
                storedRules.replaceAndSync(original);
            }
            if (deletion != null) {
                deletion.rollback();
            }
            throw asStoreUpdateFailure(e);
        }
    }

    private Entry entryForSave(String description, String recordedName) {
        ResolvedFile resolvedFile = resolveRecordedFile(recordedName);
        if (resolvedFile.invalidReason != null && resolvedFile.pathExists) {
            throw new StoreUpdateFailedException("Cannot safely update stored rule '" + description + "': " + resolvedFile.invalidReason);
        }
        String normalizedDescription = description.replace("\r\n", "\n");
        Entry result = new Entry(normalizedDescription, normalizedDescription, recordedName, null, resolvedFile);
        result.shared = false;
        return result;
    }

    private boolean isSharedWithAnotherEntry(Entry entry, Properties snapshot) {
        for (String key : snapshot.stringPropertyNames()) {
            if (key.equals(entry.propertyKey)) {
                continue;
            }
            String value = snapshot.getProperty(key);
            if (entry.recordedName.equals(value)) {
                return true;
            }
            if (entry.resolvedFile != null && entry.resolvedFile.path != null) {
                ResolvedFile other = resolveRecordedFile(value);
                if (other.path != null && sameFile(entry.resolvedFile.path, other.path)) {
                    return true;
                }
            }
        }
        return false;
    }

    private String nameFor(String description) {
        String name;
        try {
            name = ruleViolationFileNameStrategy.createRuleFileName(description);
        } catch (RuntimeException e) {
            throw new StoreUpdateFailedException(e);
        }
        if (name == null || name.trim().isEmpty()) {
            throw new StoreUpdateFailedException("Rule violation file name strategy returned no name for rule '" + description + "'");
        }
        return name;
    }

    private Path safeNewFilePath(String fileName) {
        Path path = safePath(fileName, false);
        if (path == null || STORED_RULES_FILE_NAME.equals(fileName)) {
            throw new StoreUpdateFailedException("Rule violation file name must name a regular file directly in the store folder and must not be stored.rules: " + fileName);
        }
        if (existsWithoutFollowingLinks(path)) {
            throw new StoreUpdateFailedException("Rule violation file already exists or is occupied: " + fileName);
        }
        Properties snapshot = storedRules.snapshot();
        for (String key : snapshot.stringPropertyNames()) {
            String recordedName = snapshot.getProperty(key);
            if (fileName.equals(recordedName)) {
                throw new StoreUpdateFailedException("Rule violation file name is already recorded for another rule: " + fileName);
            }
            ResolvedFile recorded = resolveRecordedFile(recordedName);
            if (recorded.path != null && sameFile(path, recorded.path)) {
                throw new StoreUpdateFailedException("Rule violation file name is already occupied by another rule: " + fileName);
            }
        }
        return path;
    }

    private Path safeExistingFilePath(String fileName) {
        if (isIndexPath(fileName)) {
            throw new StoreUpdateFailedException("A rule violation file must not be stored.rules");
        }
        Path path = safePath(fileName, true);
        ResolvedFile resolved = resolveRecordedFile(fileName);
        if (resolved.invalidReason != null) {
            if (!resolved.pathExists && path != null) {
                return path;
            }
            throw new StoreUpdateFailedException("Cannot safely update rule violation file '" + fileName + "': " + resolved.invalidReason);
        }
        return resolved.path;
    }

    private Path safePath(String fileName, boolean allowMissing) {
        try {
            File candidate = new File(storeFolder, fileName);
            File canonical = candidate.getCanonicalFile();
            File canonicalFolder = storeFolder.getCanonicalFile();
            if (!canonicalFolder.equals(canonical.getParentFile())) {
                return null;
            }
            if (!allowMissing && existsWithoutFollowingLinks(candidate.toPath())) {
                return null;
            }
            return canonical.toPath();
        } catch (IOException e) {
            return null;
        }
    }

    private void writeNewFile(Path target, List<String> violations) {
        try {
            writeFileAtomically(target, encodedViolations(violations), false);
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private void writeFile(Path target, List<String> violations) {
        try {
            writeFileAtomically(target, encodedViolations(violations), true);
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private byte[] encodedViolations(List<String> violations) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append('\n');
        }
        return builder.toString().getBytes(UTF_8);
    }

    private void writeFileAtomically(Path target, byte[] content, boolean replace) throws IOException {
        Path temporary = Files.createTempFile(storeFolder.toPath(), ".archunit-violation-", ".tmp");
        try {
            Files.write(temporary, content, StandardOpenOption.TRUNCATE_EXISTING);
            if (replace) {
                moveReplacing(temporary, target);
            } else {
                moveWithoutReplacing(temporary, target);
            }
        } finally {
            Files.deleteIfExists(temporary);
        }
    }

    private String escape(String violation) {
        return violation.replace("\r", "\\\r").replace("\n", "\\\n");
    }

    private String unescape(String violation) {
        return violation.replace("\\\r", "\r").replace("\\\n", "\n");
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        synchronized (storedRules) {
            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
            Path file = safeReadPath(ruleDetailsFileName);
            List<String> result = readLines(file);
            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
            return result;
        }
    }

    private Path safeReadPath(String fileName) {
        ResolvedFile resolved = resolveRecordedFile(fileName);
        if (resolved.path == null) {
            throw new StoreReadException(new IOException("Unsafe stored rule file name: " + fileName));
        }
        return resolved.path;
    }

    private List<String> readLines(Path file) {
        String violationsText = readStoreFile(file);
        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
                .filter(line -> !onlyLineBreaks(line))
                .map(this::unescape)
                .collect(toList());
    }

    private boolean onlyLineBreaks(String value) {
        for (int i = 0; i < value.length(); i++) {
            if (value.charAt(i) != '\r') {
                return false;
            }
        }
        return true;
    }

