+        for (Entry entry : entries) {
+            if (entry.derivedName != null) {
+                collisions.computeIfAbsent(entry.derivedName, __ -> new ArrayList<>()).add(entry);
+            }
+        }
+        for (List<Entry> collision : collisions.values()) {
+            if (collision.size() > 1) {
+                for (Entry entry : collision) {
+                    entry.colliding = true;
+                }
+            }
+        }
+
+        for (Entry entry : entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.resolvedFile.invalidReason != null) {
+                entry.broken = true;
