+                    continue;
+                }
+                if (!Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                boolean isOwned = false;
+                for (Path ownedFile : owned) {
+                    if (sameFile(file, ownedFile)) {
